#!/usr/bin/env bash
set -euo pipefail

function download_all {
  # Cleat is our standard library, it comes with its own vendored copy of STC and its own meson.build. Only the
  # sources, headers and docs are needed, STC's examples and tests are skipped.
  REPO_PATHS=(LICENSE readme.md meson.build include src docs stc/LICENSE stc/README.md stc/include stc/src stc/docs)
  # Latest commit as of Sep 17 2026
  download_meson_repo cleat 69bab35d35c32374e5ee98c8cd5b248001a46f39 "https://codeberg.org/sphi/cleat.git"

  # Used by the diffapp frontend
  download_javascript_package diff 5.2.0 dist/diff.js LICENSE

  ./ensure-typescript.sh
}

NORMAL="\x1b[0m"
EOL="${NORMAL}\n"
BLUE="\x1b[34m"
PINK="\x1b[35m"
GREEN="\x1b[32m"
RED="\x1b[31m"
ERROR=0
SUBDIRS=()
DEPS=()

# For dependencies that ship their own meson.build declaring a <name>_dep dependency object
function download_meson_repo {
  local NAME="$1"
  download_repo "$@"
  DEPS+=("${NAME}_dep")
}

function download_repo {
  local NAME="$1"
  local GIT_TAG="$2"
  local GIT_URL="$3"
  SUBDIRS+=("$NAME")
  rm -rf "./$NAME" "./$NAME-tmp"
  printf "${BLUE}Cloning %s files/dirs from %s...$EOL" "${#REPO_PATHS[@]}" "$GIT_URL"
  if ! git clone --quiet --no-checkout --filter=blob:none "$GIT_URL" "./$NAME-tmp"; then
    printf "${RED}git clone of %s failed$EOL" "$GIT_URL"
    ERROR=1
    return
  fi
  git -C "./$NAME-tmp" sparse-checkout init --cone
  git -C "./$NAME-tmp" sparse-checkout set "${REPO_PATHS[@]}"
  if ! git -C "./$NAME-tmp" checkout --quiet "$GIT_TAG"; then
    printf "${RED}git checkout of %s failed$EOL" "$GIT_URL"
    ERROR=1
    return
  fi
  mkdir "./$NAME"
  for FILE in "${REPO_PATHS[@]}"; do
    if test -e "./$NAME-tmp/$FILE"; then
      mkdir -p "$(dirname "./$NAME/$FILE")"
      mv "./$NAME-tmp/$FILE" "./$NAME/$FILE"
    else
      printf "${RED}expected file %s, does not exist$EOL" "$NAME/$FILE"
      ERROR=1
    fi
  done
  rm -rf "./$NAME-tmp"
  unset REPO_PATHS
}

function download_javascript_package {
  local PACKAGE="$1"
  local VERSION="$2"
  local CODE_PATH="$3"
  local LICENSE_PATH="$4"
  printf "${BLUE}Downloading ${PACKAGE} v${VERSION} from unpkg...$EOL"
  wget "https://unpkg.com/${PACKAGE}@${VERSION}/${CODE_PATH}" -O "javascript/${PACKAGE}.js"
  wget "https://unpkg.com/${PACKAGE}@${VERSION}/${LICENSE_PATH}" -O "javascript/LICENSE-${PACKAGE}"
}

function copy_libs_from_typescript {
  # tsgo's bundled libs (lib.NAME.d.ts): tttt calls them NAME.d.ts, and lib.d.ts default.d.ts
  printf "${BLUE}Copying the libs from TypeScript...$EOL"
  rm -rf lib
  mkdir lib
  for SRC in typescript/tsc/internal/bundled/libs/lib.*.d.ts; do
    cp "$SRC" "lib/$(basename "$SRC" | sed 's/^lib\.//')"
  done
  cp typescript/tsc/internal/bundled/libs/lib.d.ts lib/default.d.ts
  cp typescript/LICENSE.txt typescript/NOTICE.txt lib
  eval "$(cat ensure-typescript.sh | grep -E '^TS_(COMMIT|VERSION)=')"
  echo "These libraries come from upstream TypeScript $TS_VERSION (tsc/internal/bundled/libs)" >lib/README.txt
}

function write_meson_build {
  printf "${BLUE}Writing meson.build for %s thirdparty libraries...$EOL" "${#SUBDIRS[@]}"
  local MESON_BUILD="./meson.build"
  rm -rf "$MESON_BUILD"
  echo "# AUTOGENERATED by refresh.sh" >>"$MESON_BUILD"
  for SUBDIR in "${SUBDIRS[@]}"; do
    echo "subdir('$SUBDIR')" >>"$MESON_BUILD"
  done
  echo "thirdparty_deps = [" >>"$MESON_BUILD"
  for DEP in "${DEPS[@]:-}"; do
    test -z "$DEP" || echo "    $DEP," >>"$MESON_BUILD"
  done
  echo "]" >>"$MESON_BUILD"
}

function apply_patches {
  for PATCH_FILE in $(ls *patch.txt 2>/dev/null); do
    printf "${BLUE}Applying %s...$EOL" "$PATCH_FILE"
    cat "$PATCH_FILE" | patch -p0
  done
}

# Change directory to the directory of this script
cd "$( dirname "${BASH_SOURCE[0]}")"
printf "${BLUE}Downloading thirdparty libraries into %s...$EOL" "$PWD"

rm -rf javascript && mkdir -p javascript

download_all
copy_libs_from_typescript
write_meson_build
apply_patches

if test $ERROR == 0; then
  printf "${GREEN}Done$EOL"
else
  printf "${RED}Completed with errors$EOL"
fi
exit $ERROR
